import{_ as a,o as s,c as e,a2 as d}from"./chunks/framework.B4hAkGey.js";const m=JSON.parse('{"title":"9.1 基础入门：延迟预算分解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/09-optimization/basics.md","filePath":"guide/09-optimization/basics.md","lastUpdated":1792683941000}'),r={name:"guide/09-optimization/basics.md"};function n(o,t,i,l,p,h){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="_9-1-基础入门-延迟预算分解" tabindex="-1">9.1 基础入门：延迟预算分解 <a class="header-anchor" href="#_9-1-基础入门-延迟预算分解" aria-label="Permalink to &quot;9.1 基础入门：延迟预算分解&quot;">​</a></h1><blockquote><p>一帧画面从摄像头到远端屏幕，每毫秒花在哪里？拆解整条链路，找到最大的优化空间。</p></blockquote><hr><h2 id="_9-1-1-webrtc-延迟预算-5g-场景" tabindex="-1">9.1.1 WebRTC 延迟预算（5G 场景） <a class="header-anchor" href="#_9-1-1-webrtc-延迟预算-5g-场景" aria-label="Permalink to &quot;9.1.1 WebRTC 延迟预算（5G 场景）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>采集 ──► 编码 ──► 传输 ──► SFU ──► 传输 ──► 解码 ──► 渲染</span></span>
<span class="line"><span>  │        │        │        │        │        │        │</span></span>
<span class="line"><span> │ ~1ms   │5~15ms   │3~10ms   │5~15ms  │3~10ms   │5~15ms   │ ~5ms</span></span>
<span class="line"><span>  └─────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                       总计 ≈ 30~70ms（5G + MEC SFU）</span></span></code></pre></div><p>对比 4G + RTMP：<strong>1500~3000ms</strong></p><hr><h2 id="_9-1-2-各环节延迟详情" tabindex="-1">9.1.2 各环节延迟详情 <a class="header-anchor" href="#_9-1-2-各环节延迟详情" aria-label="Permalink to &quot;9.1.2 各环节延迟详情&quot;">​</a></h2><h3 id="_1-采集延迟-1ms" tabindex="-1">① 采集延迟：~1ms <a class="header-anchor" href="#_1-采集延迟-1ms" aria-label="Permalink to &quot;① 采集延迟：~1ms&quot;">​</a></h3><p>摄像头驱动把帧交给浏览器。几乎可以忽略。</p><h3 id="_2-编码延迟-5-15ms" tabindex="-1">② 编码延迟：5~15ms <a class="header-anchor" href="#_2-编码延迟-5-15ms" aria-label="Permalink to &quot;② 编码延迟：5~15ms&quot;">​</a></h3><p>编码器（GPU 硬编最优）把原始帧压成码流：</p><table tabindex="0"><thead><tr><th>编码器</th><th>硬编延迟</th><th>软编延迟</th><th>建议</th></tr></thead><tbody><tr><td>H264</td><td>5~10ms</td><td>30~60ms</td><td><strong>优先 GPU 硬编</strong></td></tr><tr><td>VP8/VP9</td><td>部分硬件有</td><td>30~80ms</td><td>有硬编就用</td></tr><tr><td>AV1</td><td>极少硬件</td><td>80~150ms</td><td>5G 带宽足时用</td></tr></tbody></table><p>编码参数对延迟的影响：</p><ul><li><strong>gop_size（关键帧间隔）</strong>：默认 2~4 秒，减小到 1 秒 → 首帧时间缩短，但码率略升</li><li><strong>bframes（B 帧数量）</strong>：B 帧有参考延迟。实时通信设为 <strong>0</strong></li><li><strong>码率控制模式</strong>：<strong>CBR/VBR</strong> 影响编码实时性，推荐 VBR + maxBitrate 约束</li></ul><h3 id="_3-网络传输延迟-3-50ms" tabindex="-1">③ 网络传输延迟：3~50ms <a class="header-anchor" href="#_3-网络传输延迟-3-50ms" aria-label="Permalink to &quot;③ 网络传输延迟：3~50ms&quot;">​</a></h3><p>取决于物理距离、网络类型、NAT 穿透方式：</p><table tabindex="0"><thead><tr><th>路径</th><th>典型延迟</th></tr></thead><tbody><tr><td>Host 候选（同局域网）</td><td>&lt; 1ms</td></tr><tr><td>Server-Reflexive（STUN 穿透）</td><td>5~15ms</td></tr><tr><td>Relayed（TURN 中继）</td><td>30~80ms</td></tr><tr><td>5G MEC 边缘 SFU</td><td>5~10ms</td></tr><tr><td>跨区域中心机房 SFU</td><td>50~120ms</td></tr></tbody></table><h3 id="_4-sfu-处理延迟-5-15ms" tabindex="-1">④ SFU 处理延迟：5~15ms <a class="header-anchor" href="#_4-sfu-处理延迟-5-15ms" aria-label="Permalink to &quot;④ SFU 处理延迟：5~15ms&quot;">​</a></h3><p>SFU 接收 → 选择 → 转发。Mediasoup / LiveKit 等现代 SFU 能做到 5ms 以内。</p><h3 id="_5-jitter-buffer-0-200ms-可变" tabindex="-1">⑤ Jitter Buffer：0~200ms（可变！） <a class="header-anchor" href="#_5-jitter-buffer-0-200ms-可变" aria-label="Permalink to &quot;⑤ Jitter Buffer：0~200ms（可变！）&quot;">​</a></h3><p>Jitter Buffer 用来吸收网络抖动（到达时间不均匀）。<strong>网络好时 0~10ms，弱网时自动增大到 100~200ms</strong>——这是弱网时延迟暴涨的主要原因！</p><h3 id="_6-解码-渲染-5-20ms" tabindex="-1">⑥ 解码 + 渲染：5~20ms <a class="header-anchor" href="#_6-解码-渲染-5-20ms" aria-label="Permalink to &quot;⑥ 解码 + 渲染：5~20ms&quot;">​</a></h3><p>解码（GPU 硬解）+ 渲染到屏幕。浏览器做了很多优化，基本稳定。</p><hr><h2 id="_9-1-3-延迟优化优先级" tabindex="-1">9.1.3 延迟优化优先级 <a class="header-anchor" href="#_9-1-3-延迟优化优先级" aria-label="Permalink to &quot;9.1.3 延迟优化优先级&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 编码（硬编替代软编，设 bframes=0）     ← 立竿见影</span></span>
<span class="line"><span>2. SFU 部署（MEC 边缘节点）              ← 5G 时代必做</span></span>
<span class="line"><span>3. ICE 穿透（Host &gt; STUN &gt; TURN）        ← 保证穿透率</span></span>
<span class="line"><span>4. Jitter Buffer（弱网时手动控制）        ← 高级调优</span></span>
<span class="line"><span>5. 编解码器选择（H264 &gt; VP9 &gt; AV1）      ← 硬件加速优先</span></span>
<span class="line"><span>6. simulcast（多码率，弱网时自动降）       ← 体验优化</span></span></code></pre></div><hr><h2 id="_9-1-4-qoe-核心指标" tabindex="-1">9.1.4 QoE 核心指标 <a class="header-anchor" href="#_9-1-4-qoe-核心指标" aria-label="Permalink to &quot;9.1.4 QoE 核心指标&quot;">​</a></h2><p>实时监控以下指标来判断直播质量：</p><table tabindex="0"><thead><tr><th>指标</th><th>目标值</th><th>采集方式</th></tr></thead><tbody><tr><td><strong>端到端延迟</strong></td><td>&lt; 300ms（互动场景）</td><td>发送端打时间戳，接收端对比</td></tr><tr><td><strong>发送码率</strong></td><td>&gt; 1Mbps（720p）</td><td><code>pc.getStats()</code> → outbound-rtp</td></tr><tr><td><strong>接收丢包率</strong></td><td>&lt; 1%</td><td><code>pc.getStats()</code> → inbound-rtp.packetsLost / packetsReceived</td></tr><tr><td><strong>抖动 jitter</strong></td><td>&lt; 30ms</td><td><code>pc.getStats()</code> → inbound-rtp.jitter</td></tr><tr><td><strong>实际分辨率</strong></td><td>≥ 预期 80%</td><td><code>pc.getStats()</code> → frameWidth / frameHeight</td></tr><tr><td><strong>实际帧率</strong></td><td>≥ 预期 80%</td><td><code>pc.getStats()</code> → framesPerSecond</td></tr><tr><td><strong>ICE 连接成功率</strong></td><td>&gt; 95%</td><td>自建监控统计</td></tr><tr><td><strong>重连次数</strong></td><td>&lt; 1 次/小时</td><td>客户端埋点</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./advanced">9.2 进阶应用：带宽估计与拥塞控制</a></p>`,34)])])}const b=a(r,[["render",n]]);export{m as __pageData,b as default};
